#!/usr/bin/env node
// Structural inspector for the watchOS target generated by `expo prebuild`
// + @bacons/apple-targets. Asserts:
//   - exactly one phone (.application + SDKROOT=iphoneos) target
//   - exactly one watch (.application + SDKROOT=watchos) target
//   - watch Info.plist has WKApplication=true, CFBundleShortVersionString == phone version
//   - watch bundle id == <phone bundle id>.watchkitapp
//   - both targets' entitlements contain App Group group.com.optimisedigital.nevermisstwice
// No external deps. Uses macOS `plutil` to parse plists (pbxproj is a plist).

import { execFileSync } from 'node:child_process';
import { readdirSync, statSync, existsSync } from 'node:fs';
import { dirname, join, resolve, isAbsolute } from 'node:path';
import { argv, exit } from 'node:process';

const APP_GROUP = 'group.com.optimisedigital.nevermisstwice';
const WATCH_SUFFIX = '.watchkitapp';

function parseArgs(args) {
  const out = { iosDir: './ios' };
  for (let i = 2; i < args.length; i++) {
    if (args[i] === '--ios-dir') {
      out.iosDir = args[++i];
    } else if (args[i].startsWith('--ios-dir=')) {
      out.iosDir = args[i].slice('--ios-dir='.length);
    }
  }
  return out;
}

function fail(check, expected, got) {
  console.error(`FAIL: ${check} — expected ${expected}, got ${got}`);
  exit(1);
}

function plutilJson(path) {
  let raw;
  try {
    raw = execFileSync('plutil', ['-convert', 'json', '-o', '-', path], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (err) {
    fail(
      `plutil parse of ${path}`,
      'successful parse',
      `plutil error: ${err.stderr?.toString() || err.message}`,
    );
  }
  try {
    return JSON.parse(raw);
  } catch (err) {
    fail(`JSON parse of plutil output for ${path}`, 'valid JSON', err.message);
  }
}

function findXcodeproj(iosDir) {
  if (!existsSync(iosDir) || !statSync(iosDir).isDirectory()) {
    fail('ios dir', `directory at ${iosDir}`, 'missing or not a directory');
  }
  const entries = readdirSync(iosDir).filter((n) => n.endsWith('.xcodeproj'));
  if (entries.length !== 1) {
    fail(
      'xcodeproj discovery',
      'exactly one .xcodeproj',
      `${entries.length} (${entries.join(', ')})`,
    );
  }
  const proj = join(iosDir, entries[0]);
  const pbx = join(proj, 'project.pbxproj');
  if (!existsSync(pbx)) {
    fail('project.pbxproj', `file at ${pbx}`, 'missing');
  }
  return { projectDir: proj, pbxprojPath: pbx };
}

function getBuildSetting(objs, target, key) {
  // Walk the target's build configurations. Returns first non-undefined
  // value across configs (Debug/Release typically match for our checks).
  // Falls back to the project-level configuration list (for SDKROOT etc).
  const cfgList = objs[target.buildConfigurationList];
  if (cfgList?.buildConfigurations) {
    for (const cfgId of cfgList.buildConfigurations) {
      const cfg = objs[cfgId];
      const v = cfg?.buildSettings?.[key];
      if (v !== undefined) return v;
    }
  }
  return undefined;
}

function getProjectBuildSetting(objs, project, key) {
  const cfgList = objs[project.buildConfigurationList];
  if (cfgList?.buildConfigurations) {
    for (const cfgId of cfgList.buildConfigurations) {
      const cfg = objs[cfgId];
      const v = cfg?.buildSettings?.[key];
      if (v !== undefined) return v;
    }
  }
  return undefined;
}

function resolveProjectRelative(projectDir, p) {
  // INFOPLIST_FILE / CODE_SIGN_ENTITLEMENTS values are relative to the
  // project dir's *parent* (the iOS dir). Xcode treats them as relative
  // to the .xcodeproj's container directory (which is `ios/`).
  if (!p) return undefined;
  if (isAbsolute(p)) return p;
  const baseDir = dirname(projectDir); // the `ios/` directory
  return resolve(baseDir, p);
}

function main() {
  const args = parseArgs(argv);
  const iosDir = resolve(args.iosDir);
  const { projectDir, pbxprojPath } = findXcodeproj(iosDir);

  const pbx = plutilJson(pbxprojPath);
  const objs = pbx.objects;
  if (!objs || typeof objs !== 'object') {
    fail('pbxproj structure', 'objects map', typeof objs);
  }

  const project = Object.values(objs).find((v) => v && v.isa === 'PBXProject');
  if (!project) fail('PBXProject', 'one PBXProject object', 'none found');

  const nativeTargets = [];
  for (const [id, obj] of Object.entries(objs)) {
    if (obj && obj.isa === 'PBXNativeTarget') {
      nativeTargets.push({ id, ...obj });
    }
  }

  // Classify targets that are productType = application.
  const appTargets = nativeTargets.filter(
    (t) => t.productType === 'com.apple.product-type.application',
  );

  if (appTargets.length !== 2) {
    fail(
      'application target count',
      'exactly 2 (phone + watch)',
      `${appTargets.length} (${appTargets.map((t) => t.name).join(', ') || 'none'})`,
    );
  }

  const classified = appTargets.map((t) => {
    let sdkroot = getBuildSetting(objs, t, 'SDKROOT');
    if (!sdkroot) {
      // Inherit from project-level build settings.
      sdkroot = getProjectBuildSetting(objs, project, 'SDKROOT');
    }
    return { target: t, sdkroot };
  });

  const phones = classified.filter((c) => c.sdkroot === 'iphoneos');
  const watches = classified.filter((c) => c.sdkroot === 'watchos');

  if (phones.length !== 1) {
    fail(
      'phone target',
      'exactly one application target with SDKROOT=iphoneos',
      `${phones.length} (sdkroots: ${classified.map((c) => `${c.target.name}=${c.sdkroot}`).join(', ')})`,
    );
  }
  if (watches.length !== 1) {
    fail(
      'watch target',
      'exactly one application target with SDKROOT=watchos',
      `${watches.length} (sdkroots: ${classified.map((c) => `${c.target.name}=${c.sdkroot}`).join(', ')})`,
    );
  }

  const phone = phones[0].target;
  const watch = watches[0].target;

  // Phone bundle id + version
  const phoneBundleId = getBuildSetting(objs, phone, 'PRODUCT_BUNDLE_IDENTIFIER');
  if (!phoneBundleId) {
    fail('phone PRODUCT_BUNDLE_IDENTIFIER', 'a bundle id string', 'unset');
  }

  // Phone Info.plist
  const phoneInfoPlistRel = getBuildSetting(objs, phone, 'INFOPLIST_FILE');
  if (!phoneInfoPlistRel) {
    fail('phone INFOPLIST_FILE', 'a relative path', 'unset');
  }
  const phoneInfoPlistPath = resolveProjectRelative(projectDir, phoneInfoPlistRel);
  if (!existsSync(phoneInfoPlistPath)) {
    fail('phone Info.plist', `file at ${phoneInfoPlistPath}`, 'missing');
  }
  const phoneInfo = plutilJson(phoneInfoPlistPath);

  // Resolve CFBundleShortVersionString — may be literal or $(MARKETING_VERSION).
  let phoneVersion = phoneInfo.CFBundleShortVersionString;
  if (typeof phoneVersion === 'string' && phoneVersion.includes('$(')) {
    phoneVersion = getBuildSetting(objs, phone, 'MARKETING_VERSION') || phoneVersion;
  }
  if (!phoneVersion) {
    fail('phone CFBundleShortVersionString', 'a version string', 'unset');
  }

  // Watch Info.plist
  const watchInfoPlistRel = getBuildSetting(objs, watch, 'INFOPLIST_FILE');
  if (!watchInfoPlistRel) {
    fail('watch INFOPLIST_FILE', 'a relative path', 'unset');
  }
  const watchInfoPlistPath = resolveProjectRelative(projectDir, watchInfoPlistRel);
  if (!existsSync(watchInfoPlistPath)) {
    fail('watch Info.plist', `file at ${watchInfoPlistPath}`, 'missing');
  }
  const watchInfo = plutilJson(watchInfoPlistPath);

  // WKApplication == true
  if (watchInfo.WKApplication !== true) {
    fail(
      'watch Info.plist WKApplication',
      'boolean true (YES)',
      JSON.stringify(watchInfo.WKApplication),
    );
  }

  // Watch CFBundleShortVersionString == phone version (resolving $() substitutions)
  let watchVersion = watchInfo.CFBundleShortVersionString;
  if (typeof watchVersion === 'string' && watchVersion.includes('$(')) {
    watchVersion = getBuildSetting(objs, watch, 'MARKETING_VERSION') || watchVersion;
  }
  if (watchVersion !== phoneVersion) {
    fail(
      'watch CFBundleShortVersionString',
      `match phone version "${phoneVersion}"`,
      JSON.stringify(watchVersion),
    );
  }

  // Watch bundle id == phone bundle id + .watchkitapp
  let watchBundleId = watchInfo.CFBundleIdentifier;
  if (
    !watchBundleId ||
    (typeof watchBundleId === 'string' && watchBundleId.includes('$(PRODUCT_BUNDLE_IDENTIFIER)'))
  ) {
    watchBundleId = getBuildSetting(objs, watch, 'PRODUCT_BUNDLE_IDENTIFIER');
  }
  const expectedWatchBundleId = `${phoneBundleId}${WATCH_SUFFIX}`;
  if (watchBundleId !== expectedWatchBundleId) {
    fail('watch bundle id', `"${expectedWatchBundleId}"`, JSON.stringify(watchBundleId));
  }

  // Entitlements: both targets must declare the App Group.
  for (const [label, target] of [
    ['phone', phone],
    ['watch', watch],
  ]) {
    const entRel = getBuildSetting(objs, target, 'CODE_SIGN_ENTITLEMENTS');
    if (!entRel) {
      fail(`${label} CODE_SIGN_ENTITLEMENTS`, 'a relative path to .entitlements', 'unset');
    }
    const entPath = resolveProjectRelative(projectDir, entRel);
    if (!existsSync(entPath)) {
      fail(`${label} entitlements file`, `file at ${entPath}`, 'missing');
    }
    const ent = plutilJson(entPath);
    const groups = ent['com.apple.security.application-groups'];
    if (!Array.isArray(groups) || !groups.includes(APP_GROUP)) {
      fail(
        `${label} App Group entitlement`,
        `array containing "${APP_GROUP}"`,
        JSON.stringify(groups),
      );
    }
  }

  console.log(
    `OK: watch target ${watch.name} bundle ${watchBundleId} WKApplication=YES App Group=${APP_GROUP} version ${watchVersion}`,
  );
  exit(0);
}

main();
